parameters.jsonBody:
={{ JSON.stringify({
  model: 'claude-sonnet-5',
  max_tokens: 3000,
  tools: [
    { type: 'web_search_20250305', name: 'web_search', max_uses: 2 },
    { name: 'submit_scored_lead', description: 'Submit lead score, news signal and full 3-step LinkedIn+email sequence.', input_schema: { type: 'object', properties: {
        lead_score: { type: 'integer' }, lead_grade: { type: 'string' }, icp_tier: { type: 'string' }, persona: { type: 'string' }, news_signal: { type: 'string' },
        linkedin_connection: { type: 'string' }, linkedin_followup_1: { type: 'string' }, linkedin_followup_2: { type: 'string' },
        email_1_subject: { type: 'string' }, email_1_body: { type: 'string' }, email_2_subject: { type: 'string' }, email_2_body: { type: 'string' }, email_3_subject: { type: 'string' }, email_3_body: { type: 'string' }
      }, required: ['lead_score','lead_grade','icp_tier','persona','linkedin_connection','linkedin_followup_1','linkedin_followup_2','email_1_subject','email_1_body','email_2_subject','email_2_body','email_3_subject','email_3_body'] } }
  ],
  messages: [{ role: 'user', content: `You are an outbound SDR agent selling AI solutions that plug into existing ERP software for small high-impact use cases across retail ecosystems.\n\nLead: ${$json['First Name']} ${$json['Last Name']}, ${$json['Title']} at ${$json['Company']} (${$json['Industry']}, ${$json['# Employees']} employees, ${$json['City']}, ${$json['Country']}).\n\n1. Search the web for news from the last 90 days about ${$json['Company']} (expansion, digital transformation, ERP/tech investment, funding). Summarize in one line as news_signal (empty string if nothing).\n2. Score the lead 0-100 using: ICP title tier max 40 (C-suite/Founder 40, VP 30, Director/Head 24, Manager 12, other 5); function relevance max 15 (ops/supply-chain/tech/finance high); industry fit max 25 (retail ecosystem core 25, adjacent supply side 16, other 6); company scale max 10 (mid-market sweet spot); revenue max 5; data completeness max 5; news bonus max 5. Grade: A>=90, B 75-89, C 55-74, D<55.\n3. Write the 3-step sequence (LinkedIn connection <=300 chars + 2 follow-ups; 3 emails with subject and body <=120 words). Mention the company by name, angle by persona, never invent statistics or customers, use placeholders {{SENDER_NAME}} and {{CALENDLY_URL}} in email bodies, opt-out line in email 3.\n\nCall submit_scored_lead.` }],
  tool_choice: { type: 'auto' }
}) }}

parameters.jsCode:
const lead = $('Only unscored rows').item.json;
const content = $json.content || [];
const tool = content.filter(b => b.type === 'tool_use' && b.name === 'submit_scored_lead').pop();
if (!tool) { throw new Error('No submit_scored_lead tool call in Claude response'); }
const r = tool.input;
return [{ json: { ...lead,
  'Lead Score': r.lead_score, 'Lead Grade': r.lead_grade, 'ICP Tier': r.icp_tier,
  'Persona': r.persona, 'News Signal': r.news_signal || '',
  'LinkedIn Connection Message': r.linkedin_connection,
  'LinkedIn Follow-Up 1': r.linkedin_followup_1, 'LinkedIn Follow-Up 2': r.linkedin_followup_2,
  'Email 1 Subject': r.email_1_subject, 'Email 1 Body': r.email_1_body,
  'Email 2 Subject': r.email_2_subject, 'Email 2 Body': r.email_2_body,
  'Email 3 Subject': r.email_3_subject, 'Email 3 Body': r.email_3_body,
  'Status': r.lead_score >= 55 ? 'Draft' : 'Parked - Low Score', 'Sequence Step': 0
} }];

